-- Users and sign-in: the auth and user modules.
-- Conventions for every table: UUIDv7 ids generated by the app, timestamptz in UTC, created_at and updated_at.

-- Keeps updated_at current on every UPDATE, whoever writes the row.
CREATE FUNCTION set_updated_at() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

CREATE TABLE users
(
    id           uuid PRIMARY KEY,
    display_name text,
    pro_until    timestamptz,
    -- Soft delete: a purge job removes the row, and everything cascading from it, 30 days later.
    deleted_at   timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX users_deleted_at_idx ON users (deleted_at) WHERE deleted_at IS NOT NULL;

-- One row per Apple or Google account. Accounts are linked explicitly, never merged by email.
CREATE TABLE user_identities
(
    id         uuid PRIMARY KEY,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    provider   text        NOT NULL CHECK (provider IN ('APPLE', 'GOOGLE')),
    -- The provider's stable user id (the token's sub claim).
    subject    text        NOT NULL,
    -- Null when the provider doesn't share it, or for Apple's private relay after the first sign-in.
    email      text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider, subject)
);

CREATE INDEX user_identities_user_id_idx ON user_identities (user_id);

-- One row per app install. The id is the device id the app sends at sign-in; signing in as someone else on the
-- same phone moves the row to that user.
CREATE TABLE devices
(
    id           uuid PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- Known only once the user allows notifications.
    apns_token   text UNIQUE,
    environment  text CHECK (environment IN ('SANDBOX', 'PRODUCTION')),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CHECK ((apns_token IS NULL) = (environment IS NULL))
);

CREATE INDEX devices_user_id_idx ON devices (user_id);

-- Rotated on every use. Only a SHA-256 hash is stored; a revoked token used again revokes every token for its device.
CREATE TABLE refresh_tokens
(
    id         uuid PRIMARY KEY,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    device_id  uuid        NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    token_hash bytea       NOT NULL UNIQUE,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX refresh_tokens_user_id_idx ON refresh_tokens (user_id);
CREATE INDEX refresh_tokens_device_id_idx ON refresh_tokens (device_id) WHERE revoked_at IS NULL;

CREATE TRIGGER users_set_updated_at BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER user_identities_set_updated_at BEFORE UPDATE ON user_identities
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER devices_set_updated_at BEFORE UPDATE ON devices
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER refresh_tokens_set_updated_at BEFORE UPDATE ON refresh_tokens
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
